import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"Kafka Event Pipeline — Quality Report (v1.31-2)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/streaming/kafka-event-pipeline-v2.md","filePath":"quality-reports/streaming/kafka-event-pipeline-v2.md"}'),r={name:"quality-reports/streaming/kafka-event-pipeline-v2.md"};function i(s,e,c,n,l,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="kafka-event-pipeline-—-quality-report-v1-31-2" tabindex="-1">Kafka Event Pipeline — Quality Report (v1.31-2) <a class="header-anchor" href="#kafka-event-pipeline-—-quality-report-v1-31-2" aria-label="Permalink to &quot;Kafka Event Pipeline — Quality Report (v1.31-2)&quot;">​</a></h1><p>Dogfood: <a href="./../../../examples/dogfood-kafka-event-pipeline/"><code>examples/dogfood-kafka-event-pipeline</code></a>. Package under exercise: <a href="./../../../packages/streaming/"><code>@kiwa-lab/streaming</code></a> (v0.3.0).</p><p>v1.31-2 extends the v1.20-2 shape (<a href="./kafka-event-pipeline">kafka-event-pipeline.md</a>) with 4 new axes drawn from the streaming v0.3 advanced semantics grid + a confluent-kafka + Schema Registry testcontainers real driver + a Playwright e2e layer. The v1.20-2 axes (idempotent producer / consumer group / exactly-once txn / DLQ) stay in place — v2 adds the raw-protocol + Schema Registry + testcontainers surface on top so the 13-axis release gate can score the full journey.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>The v1.31-2 dogfood exercises 4 v1 patterns plus 4 v2 axes.</p><h3 id="v1-still-in-place-from-v1-20-2" tabindex="-1">v1 (still in place from v1.20-2) <a class="header-anchor" href="#v1-still-in-place-from-v1-20-2" aria-label="Permalink to &quot;v1 (still in place from v1.20-2)&quot;">​</a></h3><ol><li>Idempotent producer — partition-key hashing + batch send + duplicate sequence-number dedup (<code>src/producer/index.ts</code>).</li><li>Consumer group — 2 consumers join a group, round-robin partition assignment, per-consumer offset commit + rebalance callback (<code>src/consumer/index.ts</code>).</li><li>Exactly-once transactional producer — <code>initTransactions</code> + <code>beginTransaction</code> + <code>send</code> + <code>commit</code> / <code>abort</code>, aborted batches never reach the broker, read-committed consumers see only committed records (<code>src/transaction/index.ts</code>).</li><li>DLQ — retry policy (constant / linear / exponential backoff), poison message quarantine, DLQ topic republish + replay path (<code>src/dlq/index.ts</code>).</li></ol><h3 id="v2-new-in-v1-31-2" tabindex="-1">v2 (new in v1.31-2) <a class="header-anchor" href="#v2-new-in-v1-31-2" aria-label="Permalink to &quot;v2 (new in v1.31-2)&quot;">​</a></h3><ol start="5"><li>KIP-98 raw protocol — <code>initProducerId</code> + <code>fenceProducer</code> (epoch bump) + txn coordinator state machine walk (<code>Empty</code> → <code>Ongoing</code> → <code>PrepareCommit</code> → <code>CompleteCommit</code> → <code>Empty</code>) + incremental fetch session (KIP-227). Exercised through the <code>driveRawProtocol</code> adapter op wired to <code>createKafkaRawProtocol</code> from <code>@kiwa-lab/streaming</code> v0.3.</li><li>ISR + high-watermark — 3-broker ISR attach + HW advance past <code>min.insync.replicas</code> gate. Exercised through the <code>driveIsrHighWatermark</code> adapter op.</li><li>Redpanda Schema Registry evolution — subject registration + <code>BACKWARD</code> / <code>FORWARD</code> / <code>FULL</code> compatibility check. Exercised through the <code>driveSchemaRegistry</code> adapter op wired to <code>createRedpandaSchemaEvolution</code>.</li><li>confluent-kafka + Schema Registry testcontainers probe — env-gated (<code>KIWA_MODE=real</code> + <code>KAFKA_KEY</code>) real driver that boots a Kafka 3.7 + Schema Registry container pair through a duck-typed <code>testcontainers</code> module (soft peer dep, degrades to <code>KAFKA_ENV_MISSING</code> when Docker or the peer dep is missing).</li></ol><p>All 8 axes drive through the provider-neutral 9-op adapter surface (5 v1 ops + 4 v2 ops).</p><h2 id="release-gate-—-13-axis-verdict-mock-trace" tabindex="-1">Release gate — 13-axis verdict (mock trace) <a class="header-anchor" href="#release-gate-—-13-axis-verdict-mock-trace" aria-label="Permalink to &quot;Release gate — 13-axis verdict (mock trace)&quot;">​</a></h2><p>Snapshot from <code>examples/dogfood-kafka-event-pipeline/quality-report/fidelity-latest.md</code>, which is generated locally by <code>pnpm -F dogfood-kafka-event-pipeline test</code> and is not tracked in the repository (see #1395).</p><table tabindex="0"><thead><tr><th>axis</th><th>value</th><th>gate</th></tr></thead><tbody><tr><td>coverage — line</td><td>93.00%</td><td>PASS</td></tr><tr><td>coverage — branch</td><td>89.00%</td><td>PASS</td></tr><tr><td>coverage — function</td><td>96.00%</td><td>PASS</td></tr><tr><td>test count — behavior</td><td>52</td><td>PASS (&gt;= 10)</td></tr><tr><td>fidelity — ratio</td><td>88.89% (8/9)</td><td>PASS (&gt;= 70)</td></tr><tr><td>perf — p95</td><td>5.48ms</td><td>PASS (&lt;= 100ms)</td></tr><tr><td>mutation — killRate</td><td>80.00% (32/40)</td><td>PASS (&gt;= 60)</td></tr><tr><td>mutation — tier (framework)</td><td>80.00%</td><td>PASS (&gt;= 70)</td></tr><tr><td>a11y — tier (framework)</td><td>0 / 0 / 0 (critical / serious / moderate)</td><td>PASS</td></tr><tr><td><strong>release gate verdict</strong></td><td><strong>PASS</strong></td><td><strong>9 axes evaluated</strong> on the 13-axis SSOT lane grid</td></tr></tbody></table><p>The verdict counts 9 evaluated axes because Kafka is a non-AI-LLM provider — the 4 AI-LLM-only axes (<code>cost</code> / <code>latency</code> / <code>token</code> / <code>accuracy</code>) do not activate. The full 13-axis SSOT lane grid is (a) the 7 common axes above (b) the 4 AI-LLM axes gated on the provider prefix (c) <code>mutation.tier</code> (d) <code>a11y.tier</code> — v1.31-2 activates all common + tier lanes, leaving the AI-LLM lanes intentionally inactive.</p><h2 id="real-vs-mock-fidelity-—-9-op-grid" tabindex="-1">Real vs mock fidelity — 9-op grid <a class="header-anchor" href="#real-vs-mock-fidelity-—-9-op-grid" aria-label="Permalink to &quot;Real vs mock fidelity — 9-op grid&quot;">​</a></h2><p>The 9-op adapter surface reports 8 behavioral divergences under the default env-absent configuration — every real op returns <code>KAFKA_ENV_MISSING</code> while the mock op succeeds. These are well-defined divergences: the fidelity harness records them without failing the release gate because the real driver is scope-boxed to the testcontainers probe path in v1.31-2.</p><table tabindex="0"><thead><tr><th>op</th><th>mock</th><th>real (no env)</th><th>classification</th></tr></thead><tbody><tr><td>driveProducer</td><td>OK</td><td>KAFKA_ENV_MISSING</td><td>BEHAVIORAL_DIVERGENCE</td></tr><tr><td>driveConsumerGroup</td><td>OK</td><td>KAFKA_ENV_MISSING</td><td>BEHAVIORAL_DIVERGENCE</td></tr><tr><td>driveTransaction</td><td>OK</td><td>KAFKA_ENV_MISSING</td><td>BEHAVIORAL_DIVERGENCE</td></tr><tr><td>driveDlq</td><td>OK</td><td>KAFKA_ENV_MISSING</td><td>BEHAVIORAL_DIVERGENCE</td></tr><tr><td>emitFidelity</td><td>OK</td><td>KAFKA_ENV_MISSING</td><td>BEHAVIORAL_DIVERGENCE (trace only)</td></tr><tr><td>driveRawProtocol</td><td>OK</td><td>KAFKA_ENV_MISSING</td><td>BEHAVIORAL_DIVERGENCE</td></tr><tr><td>driveIsrHighWatermark</td><td>OK</td><td>KAFKA_ENV_MISSING</td><td>BEHAVIORAL_DIVERGENCE</td></tr><tr><td>driveSchemaRegistry</td><td>OK</td><td>KAFKA_ENV_MISSING</td><td>BEHAVIORAL_DIVERGENCE</td></tr><tr><td>driveTestcontainersProbe</td><td>OK</td><td>KAFKA_ENV_MISSING</td><td>BEHAVIORAL_DIVERGENCE (probe records unreachable)</td></tr></tbody></table><p>To probe against a live Kafka broker + Schema Registry pair, opt into real mode by setting the two gate env vars.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KIWA_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">real</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  KAFKA_KEY=kiwa-real-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  KAFKA_BOOTSTRAP=localhost:9092</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  KAFKA_SCHEMA_REGISTRY_URL=http://localhost:8081</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-kafka-event-pipeline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>When both <code>KIWA_MODE=real</code> + <code>KAFKA_KEY</code> are set, the real adapter probes broker aliveness via a TCP connect on the first bootstrap broker + reports the endpoints from <code>KAFKA_BOOTSTRAP</code> + <code>KAFKA_SCHEMA_REGISTRY_URL</code>. Higher-level ops (<code>driveProducer</code> / <code>driveConsumerGroup</code> / <code>driveTransaction</code> / <code>driveDlq</code> / <code>driveRawProtocol</code> / <code>driveIsrHighWatermark</code> / <code>driveSchemaRegistry</code>) still report <code>REAL_ADAPTER_NOT_IMPLEMENTED</code> at the v1.31-2 scope; the fidelity harness treats this as a follow-up implementation milestone (the full confluent-kafka client binding is out of scope for this Issue).</p><p>Callers who want to bring their own container pair can invoke <code>startKafkaTestcontainers()</code> from <code>src/adapters/real.ts</code>. The helper boots a Kafka 3.7 KRaft-mode container + a cp-schema-registry container through a duck-typed <code>testcontainers</code> module (soft peer dep), returns the mapped host:port pair, and exposes a <code>stop()</code> boundary the caller invokes in an <code>afterAll</code> block. A missing <code>testcontainers</code> peer dep degrades to <code>SkippedError(&#39;startKafkaTestcontainers&#39;)</code> with <code>KAFKA_ENV_MISSING</code>.</p><h2 id="playwright-e2e-—-3-spec-pack" tabindex="-1">Playwright e2e — 3 spec pack <a class="header-anchor" href="#playwright-e2e-—-3-spec-pack" aria-label="Permalink to &quot;Playwright e2e — 3 spec pack&quot;">​</a></h2><p><code>tests/e2e/</code> boots a Node HTTP server that mounts the mock adapter&#39;s 9-op surface behind JSON endpoints and drives 2 BrowserContext tabs against it. The specs skip cleanly when the Playwright browser cache is absent so <code>pnpm test:e2e</code> still passes on fresh clones.</p><ul><li><code>producer-flow.spec.ts</code> — idempotent producer duplicate-drop, raw-protocol producer id / epoch fencing + txn coordinator walk, ISR / HW advance past the target offset.</li><li><code>consumer-txn-flow.spec.ts</code> — 2 tabs against 1 consumer group observe 2 consumers with 8 records consumed, transactional producer commits 2 / aborts 1 + read-committed filter drops the aborted batch.</li><li><code>idempotent-dlq-schema-flow.spec.ts</code> — idempotent duplicate retry, DLQ quarantine + replay, Schema Registry BACKWARD-compat check, testcontainers probe mock endpoints.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>KAFKA_KEY</code> (not <code>KAFKA_BOOTSTRAP</code> alone) is the opt-in gate — this keeps CI-side accidental container boots impossible.</li><li><code>startKafkaTestcontainers()</code> is a soft-dep bring-up: the <code>testcontainers</code> npm package is not a hard dependency; callers who never boot containers do not pay the install cost.</li><li>v1.31-2 does not change the v1.20-2 behavior of the 5-op v1 surface — every v1 test still runs identical to v1.20-2. v2 is strictly additive.</li></ul>`,26)])])}const m=t(r,[["render",i]]);export{k as __pageData,m as default};
